from pathlib import Path
root = Path('products/sites/shopify-catalogue-example')
for path in sorted(root.rglob('*')):
    if not path.is_file():
        continue
    print(str(path.relative_to(root)), path.stat().st_size)
    if path.suffix.lower() in {'.py', '.md', '.txt'}:
        for number, line in enumerate(path.read_text(encoding='utf-8').splitlines(), 1):
            if any(term in line.lower() for term in ('copyright', 'licen', 'redistribut', 'attribution', 'third-party')):
                print(f'  {number}: {line[:240]}')
